class AdaptiveConstructorCheck {
 static int total;static readonly BindingFlags Flags=BindingFlags.NonPublic|BindingFlags.Instance;
 static void Check(bool value,string message){if(!value)throw new Exception(message);total++;Console.WriteLine("PASS "+message);}
 static void SelectArgument(GlassPicker picker,string flag){var options=(List<string>)typeof(GlassPicker).GetField("choices",Flags).GetValue(picker);picker.SelectedIndex=options.FindIndex(s=>s.EndsWith(flag,StringComparison.Ordinal));if(picker.SelectedIndex<0)throw new Exception("Missing argument "+flag);}
 static ZapretStrategy[] Catalog(){return Enumerable.Range(0,8).Select(i=>new ZapretStrategy{Id="base"+i,Name="Base "+i,Family=i%2==0?"Flowseal":"V",Tcp="--dpi-desync=fake --dpi-desync-repeats=3 --dpi-desync-cutoff=n3 --dpi-desync-ttl=3 --marker="+i,Udp="--dpi-desync=fake --dpi-desync-repeats=3 --dpi-desync-cutoff=n3",GameTcp="--dpi-desync=fake",GameUdp="--dpi-desync=fake",VoiceUdp="VOICE"}).ToArray();}
 static ZapretCheckReport Report(){return new ZapretCheckReport{Settings=new ZapretSettings{CheckServices=new List<string>{"youtube"}}};}
 static async Task Algorithm(){var catalog=Catalog();foreach(int limit in new[]{12,24}){var defs=AdaptiveStrategySearch.Initial(catalog,"Trial",limit,"base0");var report=Report();int measured=0;var recipes=new Dictionary<string,string>();await AdaptiveStrategySearch.Run(report,defs,catalog,"Trial",limit,CancellationToken.None,(r,choices,token,say,save)=>{foreach(var c in choices){measured++;recipes[c.Id]=c.Tcp+"\n"+c.Udp;bool good=c.Tcp.Contains("--marker=0");int ms=c.Tcp.Contains("repeats=1")?50:100;r.Rows.Add(new ZapretCheckRow{StrategyId=c.Id,Name=c.Name,Family=c.Family,CheckedAt=DateTime.Now,Services=new List<ZapretServiceResult>{new ZapretServiceResult{Id="youtube",Access=good?ServiceAccess.Available:ServiceAccess.Unavailable,Milliseconds=ms,SuccessfulRequests=good?2:0}}});}r.Complete=true;save(r);return Task.FromResult(0);},s=>{},r=>{});Check(measured<=limit&&report.Planned==measured,"budget "+limit);Check(report.Adaptive&&report.Complete,"adaptive completed "+limit);Check(defs.Skip(limit==12?6:8).All(d=>d.BaseId=="base0"),"only measured working base refined "+limit);Check(recipes.Values.Distinct().Count()==recipes.Count,"no duplicate recipes "+limit);var best=AdaptiveStrategySearch.BestForService(report,"youtube",true);Check(best!=null&&best.Services[0].Milliseconds==50&&report.Rows.Count(r=>r.StrategyId==best.StrategyId)==3,"winner measured three times "+limit);Check(BestServiceProfiles.Choose(report).Single().Row.StrategyId==best.StrategyId,"recommendations use confirmed winner "+limit);}
  var failed=Report();var initial=AdaptiveStrategySearch.Initial(catalog,"Failure",12,"base0");int failures=0;await AdaptiveStrategySearch.Run(failed,initial,catalog,"Failure",12,CancellationToken.None,(r,choices,token,say,save)=>{failures+=choices.Length;foreach(var c in choices)r.Rows.Add(new ZapretCheckRow{StrategyId=c.Id,Services=new List<ZapretServiceResult>{new ZapretServiceResult{Id="youtube",Access=ServiceAccess.Unavailable}}});return Task.FromResult(0);},s=>{},r=>{});Check(failures==6&&initial.Count==6,"no blind search when all bases fail");Check(BestServiceProfiles.Choose(failed).Length==0,"failed bases never recommended");
  var flaky=Report();flaky.Adaptive=true;foreach(bool ok in new[]{true,true,false})flaky.Rows.Add(new ZapretCheckRow{StrategyId="fast",Services=new List<ZapretServiceResult>{new ZapretServiceResult{Id="youtube",Access=ok?ServiceAccess.Available:ServiceAccess.Unavailable,Milliseconds=10}}});foreach(int ms in new[]{70,80,90})flaky.Rows.Add(new ZapretCheckRow{StrategyId="stable",Services=new List<ZapretServiceResult>{new ZapretServiceResult{Id="youtube",Access=ServiceAccess.Available,Milliseconds=ms}}});Check(AdaptiveStrategySearch.BestForService(flaky,"youtube",true).StrategyId=="stable","flaky fastest rejected");
  var stopped=Report();var tokenSource=new CancellationTokenSource();int saves=0;try{await AdaptiveStrategySearch.Run(stopped,AdaptiveStrategySearch.Initial(catalog,"Stop",12,"base0"),catalog,"Stop",12,tokenSource.Token,(r,c,t,p,s)=>{tokenSource.Cancel();t.ThrowIfCancellationRequested();return Task.FromResult(0);},s=>{},r=>saves++);}catch(OperationCanceledException){}Check(!stopped.Complete&&saves>0&&!String.IsNullOrEmpty(stopped.StopReason),"cancel persists partial report");
  var original=CustomStrategies.Fork(catalog[0],"First fork",new CustomStrategyDefinition[0]);original.TcpOverrides["repeats"]="6";var fork=CustomStrategies.Fork(CustomStrategies.Build(original,catalog),"Second fork",new[]{original});fork.TcpOverrides["ttl"]="4";var built=CustomStrategies.Build(fork,catalog);Check(built.Tcp.Contains("repeats=6")&&built.Tcp.Contains("ttl=4")&&built.Tcp.Contains("cutoff=n3"),"fork of fork preserves inherited changes");Check(built.VoiceUdp=="VOICE"&&!built.GameTcp.Contains("ttl="),"voice unchanged and incompatible game-only field skipped");Check(catalog[0].Tcp.Contains("ttl=3")&&catalog[0].Tcp.Contains("repeats=3"),"base remains unchanged");
 }
 [STAThread]static int Main(string[] args){try{Algorithm().GetAwaiter().GetResult();string root=Path.GetFullPath(args[0]);Directory.CreateDirectory(root);Environment.SetEnvironmentVariable("MCRF_DATA_DIR",root);Environment.SetEnvironmentVariable("SPLIFY_WIN_DATA_DIR",root);Environment.SetEnvironmentVariable("MCRF_TEST_NO_STARTUP_SETUP","1");Environment.SetEnvironmentVariable("MCRF_TEST_NO_STARTUP_UPDATES","1");using(var form=new MainForm(false,false)){form.Size=new Size(1366,929);form.Show();Application.DoEvents();var state=(ClientState)typeof(MainForm).GetField("state",Flags).GetValue(form);state.AdvancedMode=true;UiTheme.Simple=true;SynchronizationContext.SetSynchronizationContext(new WindowsFormsSynchronizationContext());typeof(MainForm).GetMethod("ShowPage",Flags).Invoke(form,new object[]{"strategy-editor"});DateTime until=DateTime.Now.AddSeconds(30);while(form.Controls.Find("strategyEditorBasis",true).Length==0&&DateTime.Now<until){Application.DoEvents();Thread.Sleep(10);}var picker=form.Controls.Find("strategyEditorBasis",true).OfType<GlassPicker>().Single();var runtime=(ZapretRuntime)typeof(MainForm).GetField("zapret",Flags).GetValue(form);var catalog=ZapretCatalog.Load(runtime.DirectoryPath).Where(s=>s.Available&&!String.IsNullOrWhiteSpace(s.Tcp)).ToArray();int alt8=Array.FindIndex(catalog,s=>s.Id.IndexOf("ALT8",StringComparison.OrdinalIgnoreCase)>=0);Check(alt8>=0,"ALT8 offered as basis");picker.SelectedIndex=alt8;Application.DoEvents();var name=form.Controls.Find("strategyForkName",true).OfType<TextBox>().Single();name.Text="ALT 8 fork";var repeats=form.Controls.Find("strategyEditTcprepeats",true).OfType<GlassPicker>().Single();repeats.SelectedIndex=3;var button=form.Controls.Find("strategyForkSave",true).OfType<Button>().Single();button.PerformClick();Application.DoEvents();var saved=CustomStrategies.Read(runtime.DirectoryPath).Single(d=>d.Name=="ALT 8 fork");Check(saved.TcpOverrides["repeats"]=="2","constructor persists chosen field");Check(ZapretCatalog.Load(runtime.DirectoryPath).Any(s=>s.Id==saved.Id&&s.Available&&s.Name.Contains("ALT 8 fork")),"copy available in shared catalog");
   string script="set GameFilter=1024-65535\r\nset GameFilterTCP=1024-65535\r\nset GameFilterUDP=1024-65535\r\n"+BatStrategyConfig.ReadBasis(catalog[alt8],runtime.DirectoryPath);var imported=CustomStrategies.Fork(catalog[alt8],"ALT8 full",new CustomStrategyDefinition[0]);imported.BatConfig=script;var fullBuilt=CustomStrategies.Build(imported,catalog);var portable=CustomStrategies.Fork(catalog[alt8],"Portable",new CustomStrategyDefinition[0]);portable.BatConfig=System.Text.RegularExpressions.Regex.Replace(script,@"(?im)^set ""BIN=.*$",m=>"set "+(char)34+"BIN=%~dp0bin\\"+(char)34);Check(CustomStrategies.Build(portable,catalog).CustomProfiles.Length==fullBuilt.CustomProfiles.Length,"pasted BAT BIN resolves to bundled payload directory");Check(fullBuilt.CustomProfiles.Length>=4,"full ALT8 preserves multiple BAT blocks");string arguments=runtime.BuildArguments(new ZapretSettings{ScopeText="discord.com",MatchMode="addresses"},fullBuilt,Path.Combine(root,"bat"));Check(System.Text.RegularExpressions.Regex.Matches(arguments,"--hostlist=").Count==fullBuilt.CustomProfiles.Length&&!arguments.Contains("list-general.txt"),"every imported block is scoped to MCRF route");string filter=Path.Combine(root,"bat.filter");using(var process=System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo(runtime.AppExecutable(),arguments+" --wf-save="+ZapretRuntime.Quote(filter)){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true})){var output=process.StandardOutput.ReadToEndAsync();var error=process.StandardError.ReadToEndAsync();if(!process.WaitForExit(10000)){process.Kill();throw new Exception("export timeout");}Task.WaitAll(output,error);Check(process.ExitCode==0&&File.Exists(filter),"real engine accepts imported ALT8 without capture: "+output.Result+error.Result);}
   Check(BatStrategyConfig.Parse("set N=4\r\nstart winws.exe --filter-tcp=443 --dpi-desync=fake --dpi-desync-repeats=%N% ^\r\n--new --filter-udp=443 --dpi-desync=fake").Length==2,"BAT variables and continuation converted");try{BatStrategyConfig.Parse("--filter-tcp=443 --dpi-desync-repeats=%MISSING%");throw new Exception("missing variable accepted");}catch(FormatException){Check(true,"missing variable rejected");}try{BatStrategyConfig.Parse("--filter-tcp=443 --unknown-parameter=yes");throw new Exception("unknown flag accepted");}catch(FormatException){Check(true,"unknown flag rejected");}
   var argument=form.Controls.Find("strategyParameterName",true).OfType<GlassPicker>().Single();var argumentValue=form.Controls.Find("strategyParameterValue",true).OfType<TextBox>().Single();var apply=form.Controls.Find("strategyParameterApply",true).OfType<Button>().Single();var remove=form.Controls.Find("strategyParameterRemove",true).OfType<Button>().Single();var bat=form.Controls.Find("strategyBatConfig",true).OfType<RichTextBox>().Single();
   var presence=form.Controls.Find("strategyArgumentPresent",true).OfType<GlassToggle>().Single();var blockPreview=form.Controls.Find("strategyBlockPreview",true).OfType<RichTextBox>().Single();var choices=form.Controls.Find("strategyParameterChoices",true).OfType<GlassPicker>().Single();SelectArgument(argument,"--dpi-desync");Check(presence.Checked&&argument.SelectedItem.StartsWith("✓ "),"existing argument is visibly marked");Check(blockPreview.Text.Contains("--dpi-desync="),"selected block preview shows current arguments");Check(!argumentValue.Parent.Visible,"preset selection hides manual input");choices.SelectedIndex=0;Check(argumentValue.Parent.Visible,"manual choice reveals input");Check(StrategyParameterEditor.ChoiceAdvice("--dpi-desync","multisplit").Contains("TCP"),"preset advice explains protocol");
   SelectArgument(argument,"--dpi-desync-repeats");argumentValue.Text="2";apply.PerformClick();Check(BatStrategyConfig.Parse(bat.Text)[0].Contains("--dpi-desync-repeats=2"),"structured editor modifies selected block");remove.PerformClick();Check(!BatStrategyConfig.Parse(bat.Text)[0].Contains("--dpi-desync-repeats="),"structured editor removes entire argument");Check(BatStrategyConfig.Parse(bat.Text).Length==fullBuilt.CustomProfiles.Length,"structured edits preserve all remaining blocks");Check(!presence.Checked&&argument.SelectedItem.StartsWith("○ "),"removal clears presence marker");Check(!blockPreview.Text.Contains("--dpi-desync-repeats="),"preview updates after removal");
   SelectArgument(argument,"--dpi-desync-fooling");argumentValue.Text="badsum";apply.PerformClick();Check(BatStrategyConfig.Parse(bat.Text)[0].Contains("--dpi-desync-fooling=badsum"),"fooling can be added when absent in basis");
   SelectArgument(argument,"--dpi-desync");argumentValue.Text="fake";apply.PerformClick();Check(BatStrategyConfig.Parse(bat.Text)[0].Contains("--dpi-desync=fake"),"desync mode editable");
   var files=form.Controls.Find("strategyPayloadFile",true).OfType<GlassPicker>().Single();files.SelectedIndex=0;Check(argumentValue.Text.EndsWith(".bin\"")&&File.Exists(argumentValue.Text.Trim('"')),"payload picker uses actual bundled BIN files");
   name.Text="ALT8 structured fork";button.PerformClick();var structured=CustomStrategies.Read(runtime.DirectoryPath).Single(d=>d.Name==name.Text);Check(CustomStrategies.Build(structured,catalog).CustomProfiles[0].Contains("fooling=badsum"),"structured fork persisted and reconstructed");Check(catalog[alt8].Tcp==ZapretCatalog.Load(runtime.DirectoryPath).First(c=>c.Id==catalog[alt8].Id).Tcp,"structured fork never changes original");
   string edited=StrategyParameterEditor.Change("--filter-tcp=443 --dpi-desync=fake","--dpi-desync-ttl","4",false);Check(edited.Contains("ttl=4"),"missing TTL can be added");Check(!StrategyParameterEditor.Change(edited,"--dpi-desync-ttl","",true).Contains("ttl="),"TTL can be removed");Check(StrategyParameterEditor.Change(edited,"--hostcase","",false).EndsWith("--hostcase"),"argument without value supported");Check(BatStrategyConfig.Parse("--filter-tcp=443 --dpi-desync=fake --orig-ttl=64 --hostcase").Length==1,"tamper arguments import supported");Check(!StrategyParameterEditor.IsEditable("--wf-raw")&&!StrategyParameterEditor.IsEditable("--mcrf-apps"),"capture and route scope remain protected");
   var toggle=form.Controls.Find("strategyFullConfig",true).OfType<GlassToggle>().Single();toggle.Checked=true;bat.Text=script;name.Text="ALT8 full editor";button.PerformClick();Check(CustomStrategies.Read(runtime.DirectoryPath).Any(d=>d.Name=="ALT8 full editor"&&d.BatConfig.Replace("\r","")==script.Replace("\r","")),"full config saved in MCRF format");
   foreach(var size in new[]{new Size(1366,929),new Size(1050,680)}){form.Size=size;Application.DoEvents();var scroll=form.Controls.Find("strategyEditorScroll",true).Single();Check(scroll.Height>=100&&scroll.Width>600,"scroll layout "+size);var overlay=(Panel)typeof(MainForm).GetField("popupOverlay",Flags).GetValue(form);using(var image=new Bitmap(overlay.Width,overlay.Height)){overlay.DrawToBitmap(image,new Rectangle(Point.Empty,overlay.Size));image.Save(Path.Combine(root,"constructor-"+size.Width+".png"));}}var cancel=form.Controls.Find("strategyEditorCancel",true).OfType<Button>().Single();int savedCount=CustomStrategies.Read(runtime.DirectoryPath).Count;cancel.PerformClick();Application.DoEvents();Check((string)typeof(MainForm).GetField("page",Flags).GetValue(form)=="zapret","Cancel returns to Zapret");Check(CustomStrategies.Read(runtime.DirectoryPath).Count==savedCount,"Cancel does not save or delete copies");form.Close();}Console.WriteLine("OK "+total+" checks");return 0;}catch(Exception ex){Console.WriteLine(ex);return 1;}}
